<template>
  <section class="payer-rules panel" aria-label="Payer coverage and service rules">
    <h3>Payer coverage categories</h3>
    <p>A payer route may support more than one category, such as United handling both Commercial and Medicaid. The client’s primary coverage and any Medicaid secondary coverage determine their available codes. Medicaid secondary services follow the primary-first ERA/EOB workflow.</p>
    <p v-if="!rules.available" role="status">Payer rule storage needs setup before these rules can be saved.</p>
    <label>Find a payer<input v-model="payerSearch" type="search" placeholder="Payer name" /></label>
    <div class="table-scroll"><table><thead><tr><th>Payer</th><th>Coverage categories</th><th></th></tr></thead><tbody><tr v-for="payer in visiblePayers" :key="payer.payerId"><th scope="row">{{ payer.name }}</th><td><label v-for="program in rules.programs" :key="program.id" class="program-chip"><input type="checkbox" :checked="payer.programs.includes(program.id)" :disabled="saving || !rules.available" @change="setPayerProgram(payer,program.id,$event.target.checked)" />{{ program.label }}</label></td><td><button type="button" :disabled="saving || !rules.available" @click="openOverrides(payer)">Individual service override</button></td></tr><tr v-if="!visiblePayers.length"><td colspan="3">Add a verified payer route in Payer connections to classify it here.</td></tr></tbody></table></div>

    <h3>Provider categories allowed by coverage</h3>
    <p>These practice filters combine with the provider’s code permissions, client coverage, enrollment, and payer requirements.</p>
    <div class="table-scroll"><table><thead><tr><th>Coverage category</th><th v-for="tier in tiers" :key="tier.id">{{ tier.label }}</th></tr></thead><tbody><tr v-for="program in rules.programs" :key="program.id"><th scope="row">{{ program.label }}</th><td v-for="tier in tiers" :key="tier.id"><button type="button" role="switch" :aria-checked="!!rules.programTiers?.[program.id]?.[tier.id]" :aria-label="`${program.label}: ${tier.label}`" :disabled="saving || !rules.available" @click="emit('change',{kind:'program_credential',program:program.id,credentialTier:tier.id,allowed:!rules.programTiers?.[program.id]?.[tier.id]})">{{ rules.programTiers?.[program.id]?.[tier.id] ? 'On' : 'Off' }}</button></td></tr></tbody></table></div>

    <section v-if="selectedPayer" ref="overridePanel" tabindex="-1" class="override-panel" aria-label="Individual payer service overrides">
      <header><h3>Individual service override · {{ selectedPayer.name }}</h3><button type="button" @click="overridePayerId=''">Close</button></header>
      <p>Allow or block a service for this exact payer and coverage category. A Medicaid exception will not enable the service for a Commercial client on the same payer route. Provider code permissions still apply.</p>
      <div class="override-fields"><label>Coverage category<select v-model="overrideProgram"><option value="">Select category</option><option v-for="program in rules.programs.filter(p=>selectedPayer.programs.includes(p.id))" :key="program.id" :value="program.id">{{ program.label }}</option></select></label><label>Exact plan/product, if narrower<input v-model="planType" maxlength="100" placeholder="All plans in this category" /></label><label>Effective from<input v-model="effectiveFrom" type="date" /></label><label>Effective through<input v-model="effectiveThrough" type="date" :min="effectiveFrom" /></label><label>Reason<input v-model="reason" minlength="10" maxlength="1000" /></label><label>Payer policy / confirmation reference<input v-model="policyReference" minlength="5" maxlength="1000" /></label><label>Find a service<input v-model="serviceSearch" type="search" placeholder="Code or description" /></label></div>
      <p v-if="!selectedPayer.programs.length">Classify this payer’s coverage categories above before adding an override.</p>
      <div class="table-scroll"><table><thead><tr><th>Service</th><th>Category default</th><th>Individual override</th><th></th></tr></thead><tbody><tr v-for="code in visibleServices" :key="`${overridePayerId}:${overrideProgram}:${planType}:${code.code}`"><th scope="row">{{ code.code }} <span>{{ code.description }}</span></th><td>{{ overrideProgram ? code.payerPrograms?.[overrideProgram] ? 'Allowed' : 'Blocked' : 'Select category' }}</td><td><select :value="edits[code.code] ?? savedChoice(code.code)" :disabled="saving || !overrideProgram" :aria-label="`Override ${code.code}`" @change="edits[code.code]=$event.target.value"><option value="inherit">Use category default</option><option value="allow">Allow for this payer/category</option><option value="deny">Block for this payer/category</option></select><small v-if="savedOverride(code.code)">{{ savedOverride(code.code).effective_from }}–{{ savedOverride(code.code).effective_through }} <button type="button" :disabled="saving" @click="editPeriod(code.code)">Edit saved period</button></small></td><td><button type="button" :disabled="saving || !validOverride || edits[code.code] === undefined" @click="saveOverride(code)">Save override</button></td></tr></tbody></table></div>
    </section>
  </section>
</template>
<script setup>
import {computed,ref,nextTick,watch} from 'vue';
const props=defineProps({rules:{type:Object,required:true},codes:{type:Array,default:()=>[]},tiers:{type:Array,default:()=>[]},saving:Boolean});
const emit=defineEmits(['change']);
const payerSearch=ref(''),serviceSearch=ref(''),overridePayerId=ref(''),overrideProgram=ref(''),planType=ref(''),effectiveFrom=ref(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Denver'}).format(new Date())),effectiveThrough=ref(''),reason=ref(''),policyReference=ref(''),edits=ref({}),overridePanel=ref(null);
const visiblePayers=computed(()=>(props.rules.payers || []).filter(p=>p.name.toLowerCase().includes(payerSearch.value.trim().toLowerCase())));
const selectedPayer=computed(()=>(props.rules.payers || []).find(p=>p.payerId===overridePayerId.value));
const visibleServices=computed(()=>props.codes.filter(code=>`${code.code} ${code.description}`.toLowerCase().includes(serviceSearch.value.trim().toLowerCase())));
const validOverride=computed(()=>overrideProgram.value && effectiveFrom.value && effectiveThrough.value>=effectiveFrom.value && reason.value.trim().length>=10 && policyReference.value.trim().length>=5);
function setPayerProgram(payer,program,allowed){const values=new Set(payer.programs);if(allowed)values.add(program);else values.delete(program);emit('change',{kind:'payer_programs',payerId:payer.payerId,programs:[...values]});}
async function openOverrides(payer){overridePayerId.value=payer.payerId;overrideProgram.value=payer.programs.length===1?payer.programs[0]:'';edits.value={};await nextTick();overridePanel.value?.scrollIntoView?.({behavior:'smooth',block:'start'});overridePanel.value?.focus?.({preventScroll:true});}
function savedOverride(code){return (props.rules.overrides || []).filter(row=>row.payer_id===overridePayerId.value && row.program===overrideProgram.value && row.plan_type===planType.value.trim() && row.service_code===code).sort((a,b)=>b.effective_from.localeCompare(a.effective_from))[0];}
const savedChoice=code=>{const row=savedOverride(code);return row?.allowed==null?'inherit':Number(row.allowed)===1?'allow':'deny';};
function editPeriod(code){const row=savedOverride(code);if(!row)return;effectiveFrom.value=row.effective_from;effectiveThrough.value=row.effective_through;reason.value=row.reason;policyReference.value=row.policy_reference;edits.value={[code]:savedChoice(code)};}
function saveOverride(code){const choice=edits.value[code.code];emit('change',{kind:'payer_service',payerId:overridePayerId.value,program:overrideProgram.value,planType:planType.value.trim(),serviceCode:code.code,allowed:choice==='inherit'?null:choice==='allow',effectiveFrom:effectiveFrom.value,effectiveThrough:effectiveThrough.value,reason:reason.value,policyReference:policyReference.value});}
watch(()=>props.rules.revision,()=>{edits.value={};});
watch([overrideProgram,planType],()=>{edits.value={};});
</script>
<style scoped>
.panel{padding:18px;border:1px solid #e4e7ec;border-radius:12px;margin:18px 0;background:#fff}h3{margin:0 0 8px}p{color:#526477;line-height:1.5}.table-scroll{overflow-x:auto;margin:14px 0 24px}table{width:100%;border-collapse:collapse;text-align:left}td,th{padding:11px;border-bottom:1px solid #e6ebf1;vertical-align:middle}.program-chip{display:inline-flex;align-items:center;gap:5px;border:1px solid #cbd5e1;border-radius:999px;padding:6px 9px;margin:4px;font-size:13px;white-space:nowrap}label{display:grid;gap:5px;font-size:13px}input:not([type=checkbox]),select{padding:8px;border:1px solid #cbd5e1;border-radius:7px;color:inherit;background:#fff;max-width:100%;box-sizing:border-box}button{border:1px solid #bbc9d8;border-radius:8px;background:#f3f7fb;padding:8px 11px;cursor:pointer;color:inherit}button[aria-checked=true]{background:#e7f6ef;color:#145c38}button:disabled{opacity:.5;cursor:default}.override-panel{border-top:2px solid #7896b4;padding-top:18px}.override-panel header{display:flex;justify-content:space-between;align-items:start;gap:12px}.override-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}small{display:block;margin-top:5px}th span{font-weight:400}
</style>
